  mesh.rotation.x += 0.01;
  mesh.rotation.y += 0.01;
});

// Create a clipping plane
const clippingPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
scene.add(clippingPlane);

// Create a transformation
