## risk_management.py
import pandas as pd
from typing import Dict, Any
from pyrisk import ValueAtRisk

class RiskManagement:
    def __init__(self, data: Dict[str, pd.DataFrame]):
        self.data = data

    def calculate_risk(self) -> Dict[str, Any]:
        risk = {}
        for ticker, df in self.data.items():
            df['return'] = df['Close'].pct_change()
            df['cumulative_return'] = (1 + df['return']).cumprod()
            var = ValueAtRisk(df['return'], confidence=0.95)
            risk[ticker] = var.value
        return risk

    def manage_risk(self, risk: Dict[str, Any]) -> Dict[str, Any]:
        managed_risk = {}
        for ticker, var in risk.items():
            if var > 0.05:
                managed_risk[ticker] = 'high'
            elif var > 0.01:
                managed_risk[ticker] = 'medium'
            else:
                managed_risk[ticker] = 'low'
        return managed_risk

def run_risk_management(data: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
    risk_manager = RiskManagement(data)
    risk = risk_manager.calculate_risk()
    managed_risk = risk_manager.manage_risk(risk)
    return managed_risk
```
Note: This code assumes that the `pyrisk` library is installed and imported correctly. Also, the `ValueAtRisk` class is used to calculate the Value-at-Risk (VaR) for each asset, and the `manage_risk` method categorizes the risk level for each asset based on the VaR value.

