## user.py
from typing import Dict, List
from database import DatabaseManager

class User:
    def __init__(self, id: int, username: str, password: str, interests: List[str] = None, reading_habits: Dict[str, str] = None):
        self.id = id
        self.username = username
        self.password = password
        self.interests = interests if interests else []
        self.reading_habits = reading_habits if reading_habits else {}

    def add_interest(self, interest: str):
        self.interests.append(interest)

    def update_reading_habits(self, article: Dict[str, str]):
        self.reading_habits[article['id']] = article

    @classmethod
    def create_user(cls, db_manager: DatabaseManager, username: str, password: str, interests: List[str] = None, reading_habits: Dict[str, str] = None):
        user = cls(None, username, password, interests, reading_habits)
        db_manager.insert_user({
            'username': user.username,
            'password': user.password,
            'interests': ','.join(user.interests),
            'reading_habits': ','.join([f"{key}:{value}" for key, value in user.reading_habits.items()])
        })
        return user

    @classmethod
    def get_user(cls, db_manager: DatabaseManager, user_id: int):
        user_data = db_manager.get_user(user_id)
        return cls(user_id, user_data['username'], user_data['password'], [interest.strip() for interest in user_data['interests'].split(',')], {key.split(':')[0]: value for key, value in [habit.split(':') for habit in user_data['reading_habits'].split(',')]} if user_data['reading_habits'] else None)

    @classmethod
    def update_user(cls, db_manager: DatabaseManager, user: User):
        db_manager.update_user({
            'id': user.id,
            'username': user.username,
            'password': user.password,
            'interests': ','.join(user.interests),
            'reading_habits': ','.join([f"{key}:{value}" for key, value in user.reading_habits.items()])
        })
        return user
