main = Blueprint('main', __name__)

@main.route('/')
def index():
    """Returns the homepage with the search form."""
    return render_template('index.html')

@main.route('/search', methods=['POST'])
def search():
    """Returns the search results based on the query."""
    form = SearchForm(request.form)
    if form.validate():
        search_query = form.search_query.data
        songs = Song.query.filter(Song.title.like(f'%{search_query}%')).all()
        return render_template('search_results.html', songs=songs)
    return render_template('index.html', form=form)

@main.route('/song/<int:song_id>')
