## user_interface.py
import dash
import dash_core_components as dcc
import dash_html_components as html
from dash.dependencies import Input, Output
import plotly.express as px
import pandas as pd

class UserInterface:
    def __init__(self, data: Dict[str, pd.DataFrame]):
        self.data = data
        self.app = dash.Dash(__name__)

    def create_layout(self) -> html.Div:
        layout = html.Div([
            html.H1('HFT System Dashboard'),
            dcc.Graph(id='trading-data-graph'),
            dcc.Dropdown(
                id='ticker-dropdown',
                options=[{'label': ticker, 'value': ticker} for ticker in self.data.keys()],
                value=list(self.data.keys())[0]
            ),
            dcc.Interval(
                id='interval-component',
                interval=1*1000, # in milliseconds
                n_intervals=0
            )
        ])
        return layout

    def create_graph(self, ticker: str) -> dcc.Graph:
        df = self.data[ticker]
        fig = px.line(df, x=df.index, y='Close')
        return dcc.Graph(figure=fig)

    def create_callback(self) -> None:
        @self.app.callback(
            Output('trading-data-graph', 'figure'),
            [Input('interval-component', 'n_intervals'),
             Input('ticker-dropdown', 'value')]
        )
        def update_graph(n, ticker):
            return self.create_graph(ticker)

    def run(self) -> None:
        self.app.layout = self.create_layout()
        self.create_callback()
        self.app.run_server(debug=True)

def run_user_interface(data: Dict[str, pd.DataFrame]) -> None:
    ui = UserInterface(data)
    ui.run()
```
Note: This code assumes that the `data` dictionary contains pandas DataFrames with the trading data. The `create_layout` method creates the layout of the dashboard, including a dropdown menu for selecting the ticker and a graph for displaying the trading data. The `create_graph` method creates a line graph for the selected ticker. The `create_callback` method creates a callback function that updates the graph when the ticker is changed or the interval is triggered. The `run` method runs the Dash app.

