```
**JavaScript**
```javascript
const svg = document.querySelector('svg');
const parallaxLayer = document.querySelector('.parallax-layer');

let parallaxSpeed = 0.1;

function parallax() {
  const scrollPosition = window.scrollY;
  const svgHeight = svg.getBBox().height;
  const parallaxLayerHeight = parallaxLayer.offsetHeight;

  const parallaxOffset = (scrollPosition / (parallaxLayerHeight - svgHeight)) * parallaxSpeed;

  parallaxLayer.style.transform = `translateY(${parallaxOffset}px)`;
  svg.style.transform = `translateY(${parallaxOffset}px)`;

  requestAnimationFrame(parallax);
}

window.addEventListener('scroll', parallax);
```
