from rest_framework.response import Response
from rest_framework.views import APIView
from .models import User, Conference, Chat
from .serializers import UserSerializer, ConferenceSerializer, ChatSerializer

class UserView(APIView):
    def post(self, request):
        """
        Creates a new user.

        :param request: The HTTP request object.
        :return: A JSON response with the created user's details.
        """
        serializer = UserSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=201)
        return Response(serializer.errors, status=400)

class ConferenceView(APIView):
    def post(self, request):
        """
        Creates a new conference.

        :param request: The HTTP request object.
        :return: A JSON response with the created conference's details.
        """
        serializer = ConferenceSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=201)
        return Response(serializer.errors, status=400)

    def put(self, request, conference_id):
        """
        Adds a participant to a conference.

        :param request: The HTTP request object.
        :param conference_id: The ID of the conference to add the participant to.
        :return: A JSON response with the updated conference's details.
        """
        conference = Conference.objects.get(id=conference_id)
        serializer = ConferenceSerializer(conference, data=request.data, partial=True)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=200)
        return Response(serializer.errors, status=400)

class ChatView(APIView):
