from django.db import models

class User(models.Model):
    username = models.CharField(max_length=100)
    password = models.CharField(max_length=100)
    email = models.EmailField(unique=True)

    def __str__(self):
        return self.username

class Conference(models.Model):
    host = models.ForeignKey(User, on_delete=models.CASCADE, related_name='conferences')
    participants = models.ManyToManyField(User, related_name='participating_in')
    is_active = models.BooleanField(default=False)

    def __str__(self):
        return f'Conference {self.id} hosted by {self.host.username}'

class Chat(models.Model):
    sender = models.ForeignKey(User, on_delete=models.CASCADE, related_name='messages')
    conference = models.ForeignKey(Conference, on_delete=models.CASCADE, related_name='chats')
    message = models.TextField()

    def __str__(self):
        return f'Message {self.id} by {self.sender.username} in Conference {self.conference.id}'
