```python
def is_valid(board, row, col, num):
    """
    Check if it's possible to place a number in the given position.

    Args:
        board (list): The Sudoku board.
        row (int): The row index.
        col (int): The column index.
        num (int): The number to check.

    Returns:
        bool: True if the number can be placed, False otherwise.
    """
    # Check the row
    for x in range(9):
        if board[row][x] == str(num):
            return False

    # Check the column
    for x in range(9):
        if board[x][col] == str(num):
            return False

    # Check the box
    start_row = row - row % 3
    start_col = col - col % 3
    for i in range(3):
        for j in range(3):
            if board[i + start_row][j + start_col] == str(num):
                return False
    return True


def solve_sudoku(board):
    """
    Solve the Sudoku puzzle.

    Args:
        board (list): The Sudoku board.

    Returns:
        bool: True if the puzzle is solved, False otherwise.
    """
    for i in range(9):
        for j in range(9):
            if board[i][j] == '.':
                for num in range(1, 10):
                    if is_valid(board, i, j, num):
                        board[i][j] = str(num)
                        if solve_sudoku(board):
                            return True
                        board[i][j] = '.'
                return False
    return True


def print_board(board):
    """
    Print the Sudoku board.

    Args:
        board (list): The Sudoku board.
    """
    for i in range(9):
        if i % 3 == 0 and i != 0:
            print("- - - - - - - - - - - -")
        for j in range(9):
            if j % 3 == 0 and j != 0:
                print("| ", end="")
            if j == 8:
                print(board[i][j])
            else:
                print(str(board[i][j]) + " ", end="")


