## users/views.py
```python
from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from django.contrib.auth import login, authenticate, logout
from django.contrib import messages
from .forms import UserRegistrationForm, UserLoginForm
from .models import User

def register(request):
    """
    View for user registration.
    """
    if request.method == 'POST':
        form = UserRegistrationForm(request.POST)
        if form.is_valid():
            form.save()
            username = form.cleaned_data.get('username')
            messages.success(request, f'Account created for {username}!')
            return redirect('login')
    else:
        form = UserRegistrationForm()
    return render(request, 'users/register.html', {'form': form})

def login_view(request):
    """
    View for user login.
    """
    if request.method == 'POST':
        form = UserLoginForm(request.POST)
        if form.is_valid():
            username = form.cleaned_data.get('username')
            password = form.cleaned_data.get('password')
            user = authenticate(username=username, password=password)
            if user is not None:
                login(request, user)
                return redirect('home')
    else:
        form = UserLoginForm()
    return render(request, 'users/login.html', {'form': form})

@login_required
def logout_view(request):
    """
    View for user logout.
    """
    logout(request)
    return redirect('login')

def profile(request):
    """
    View for user profile.
    """
    user = request.user
    return render(request, 'users/profile.html', {'user': user})

def search(request):
    """
    View for searching users.
    """
    query = request.GET.get('q')
    users = User.objects.filter(username__icontains=query)
    return render(request, 'users/search.html', {'users': users})
```
Note: This code assumes that you have already created the necessary templates (register.html, login.html, profile.html, search.html) and forms (UserRegistrationForm, UserLoginForm) in the users app.

