from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from .models import Startup
from .forms import StartupForm

class StartupListView(ListView):
    model = Startup
    template_name = 'startups/startup_list.html'

    def get_queryset(self):
        return Startup.objects.all()

class StartupDetailView(DetailView):
    model = Startup
    template_name = 'startups/startup_detail.html'

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context['startups'] = Startup.objects.all()
        return context

class StartupCreateView(CreateView):
    model = Startup
    form_class = StartupForm
    template_name = 'startups/startup_form.html'

    def form_valid(self, form):
        form.save()
        return redirect('startup_list')

class StartupUpdateView(UpdateView):
    model = Startup
    form_class = StartupForm
    template_name = 'startups/startup_form.html'

    def form_valid(self, form):
        form.save()
        return redirect('startup_list')

class StartupDeleteView(DeleteView):
    model = Startup
    template_name = 'startups/startup_delete.html'

    def delete(self, request, *args, **kwargs):
        self.object = self.get_object()
        self.object.delete()
        return redirect('startup_list')

@login_required
def startup_list(request):
    startups = Startup.objects.all()
    return render(request, 'startups/startup_list.html', {'startups': startups})

@login_required
def startup_detail(request, pk):
    startup = Startup.objects.get(pk=pk)
    return render(request, 'startups/startup_detail.html', {'startup': startup})

@login_required
def startup_create(request):
    if request.method == 'POST':
        form = StartupForm(request.POST)
        if form.is_valid():
            form.save()
            return redirect('startup_list')
    else:
        form = StartupForm()
    return render(request, 'startups/startup_form.html', {'form': form})

@login_required
def startup_update(request, pk):
    startup = Startup.objects.get(pk=pk)
    if request.method == 'POST':
        form = StartupForm(request.POST, instance=startup)
        if form.is_valid():
            form.save()
            return redirect('startup_list')
    else:
        form = StartupForm(instance=startup)
    return render(request, 'startups/startup_form.html', {'form': form})

@login_required
def startup_delete(request, pk):
    startup = Startup.objects.get(pk=pk)
    if request.method == 'POST':
        startup.delete()
        return redirect('startup_list')
    return render(request, 'startups/startup_delete.html', {'startup': startup})
