**JavaScript**

```javascript
const parallaxLayers = document.querySelectorAll('.parallax-layer');

window.addEventListener('scroll', () => {
  const scrollPosition = window.scrollY;
  parallaxLayers.forEach((layer, index) => {
    const layerHeight = layer.offsetHeight;
    const layerTop = layer.offsetTop;
    const layerBottom = layerTop + layerHeight;
    const scrollRange = layerBottom - layerTop;
    const scrollPercentage = (scrollPosition - layerTop) / scrollRange;
    const scale = 1 + (scrollPercentage * 0.1);
    layer.style.transform = `translateZ(0) scale(${scale})`;
  });
});
