#weathered {
  /* Gradients and Blurs */
  filter: progid:DXImageTransform.Microsoft.gradient(startColorstr='#F5F5DC', endColorstr='#C0C0C0', GradientType=0);
  filter: blur(2px);
}

/* Color Desaturation */
path {
  fill: #402A32;
  fill-opacity: 0.5;
}

/* Texture Overlay */
