import numpy as np
from typing import Dict, Tuple, Set

def filter_and_sort_books(books: Dict[str, Tuple[float, float, int, int, int, float, str, str]], 
                          min_thresholds: Set[float] = None) -> list:
    """
    Filter and sort books based on the given thresholds.

    Args:
    books (Dict[str, Tuple[float, float, int, int, int, float, str, str]]): A dictionary of books where each key is a book title and each value is a tuple of book's price, rating, pages, publication year, sold copies, reviews, author, and genre.
    min_thresholds (Set[float], optional): A set of minimum thresholds for each book parameter. Defaults to None.

    Returns:
    list: A list of filtered and sorted books.
    """

    # Check if books is a dictionary
    if not isinstance(books, dict):
        raise ValueError("Books must be a dictionary")

    # Check if min_thresholds is a set
    if min_thresholds is not None and not isinstance(min_thresholds, set):
        raise ValueError("Min thresholds must be a set")

    # Check if min_thresholds is provided
    if min_thresholds is None:
        return "Min thresholds are not provided"

    # Check if books is empty
    if not books:
        return "Books dictionary is empty"

    # Check for duplicate book titles
    if len(books) != len(set(books.keys())):
        raise ValueError("Duplicate book titles found")

    # Initialize an empty list to store filtered books
    filtered_books = []

    # Iterate over each book in the dictionary
    for title, book_info in books.items():
        # Check if book_info is a tuple
        if not isinstance(book_info, tuple):
            raise ValueError(f"Book '{title}' has invalid data type")

        # Check if book_info has exactly 8 elements
        if len(book_info) != 8:
            raise ValueError(f"Book '{title}' has invalid data type")

        # Try to convert book_info to numeric types
        try:
            price, rating, pages, publication_year, sold_copies, reviews, author, genre = map(float, book_info[:5]) + [str(book_info[5]), str(book_info[6]), str(book_info[7])]
        except ValueError:
            raise ValueError(f"Book '{title}' has non-numeric values")

        # Check if book meets the minimum thresholds
        if all(threshold <= value for threshold, value in zip(min_thresholds, [price, rating, pages, publication_year, sold_copies, reviews, author, genre])):
            # Add book to the filtered list
            filtered_books.append((title, price, rating, pages, publication_year, sold_copies, reviews, author, genre))

    # Sort the filtered books based on the given parameters
    filtered_books.sort(key=lambda x: (x[4], x[1], x[2], x[5], x[6], x[0]))

    return filtered_books

