from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from .models import Paper
from .forms import PaperForm

def submit_paper(request):
    """
    Submit a new paper.
    """
    if request.method == 'POST':
        form = PaperForm(request.POST)
        if form.is_valid():
            paper = form.save(commit=False)
            paper.author = request.user
            paper.save()
            messages.success(request, 'Paper submitted successfully!')
            return redirect('home')
    else:
        form = PaperForm()
    return render(request, 'papers/submit.html', {'form': form})

@login_required
def view_papers(request):
    """
    Display a list of papers.
    """
    papers = Paper.objects.all()
    return render(request, 'papers/view_papers.html', {'papers': papers})

@login_required
def view_paper(request, pk):
    """
    Display a single paper.
    """
    paper = Paper.objects.get(pk=pk)
    return render(request, 'papers/view_paper.html', {'paper': paper})

@login_required
def edit_paper(request, pk):
    """
    Edit a paper.
    """
    paper = Paper.objects.get(pk=pk)
    if request.method == 'POST':
        form = PaperForm(request.POST, instance=paper)
        if form.is_valid():
            form.save()
            messages.success(request, 'Paper updated successfully!')
            return redirect('view_paper', pk=pk)
    else:
        form = PaperForm(instance=paper)
    return render(request, 'papers/edit_paper.html', {'form': form})

@login_required
def delete_paper(request, pk):
    """
    Delete a paper.
    """
    paper = Paper.objects.get(pk=pk)
    paper.delete()
    messages.success(request, 'Paper deleted successfully!')
    return redirect('view_papers')
